<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Employees Attendance</h1><p>Load, mark, reopen and update employee attendance</p></div></header><section class="module-card"><header class="module-card__header"><div class="mode-switch"><button class="is-active" type="button">Manual Attendance</button><button class="locked-choice" disabled><i data-lucide="lock"></i>Card Scanning</button></div></header><div class="module-card__body"><form class="filter-bar" method="get"><div class="module-field"><label>Date</label><input class="module-input" name="date" type="date" value="<?= e($selectedDate) ?>" required></div><button class="btn btn--primary">Load Employees</button></form><form method="post" action="<?= url('/admin/attendance/employees') ?>"><?= csrf_field() ?><input type="hidden" name="date" value="<?= e($selectedDate) ?>"><?php if(!$attendanceRows):?><div class="compact-empty"><h3>No active employees found</h3><p>Add an employee first.</p></div><?php else:?><div class="table-tools"><button class="btn btn--secondary" type="button" onclick="document.querySelectorAll('.employee-status').forEach(x=>x.value='Present')">Mark All Present</button></div><div class="table-scroll attendance-scroll"><table class="data-table attendance-table"><thead><tr><th>Employee</th><th>Role</th><th>Status</th><th>Time In</th><th>Time Out</th><th>Remarks</th></tr></thead><tbody><?php foreach($attendanceRows as$row):?><tr><td data-label="Employee" class="att-name"><?= e($row['name']) ?><br><small><?= e($row['employee_no']) ?></small><?php require BASE_PATH.'/app/Views/partials/person-status-tag.php'; ?></td><td data-label="Role"><?= e($row['role']) ?></td><td data-label="Status"><select class="module-select employee-status" name="status[<?= $row['id'] ?>]"><?php foreach(['Present','Absent','Leave','Late','Half Day']as$s):?><option <?= $row['attendance_status']===$s?'selected':'' ?>><?= $s ?></option><?php endforeach ?></select></td><td data-label="Time In"><input class="module-input" type="time" name="time_in[<?= $row['id'] ?>]" value="<?= e(substr((string)$row['time_in'],0,5)) ?>"></td><td data-label="Time Out"><input class="module-input" type="time" name="time_out[<?= $row['id'] ?>]" value="<?= e(substr((string)$row['time_out'],0,5)) ?>"></td><td data-label="Remarks"><input class="module-input" placeholder="Optional" name="remarks[<?= $row['id'] ?>]" value="<?= e($row['remarks']) ?>"></td></tr><?php endforeach ?></tbody></table></div><div class="module-card__footer attendance-save"><button class="btn btn--primary">Save Attendance</button></div><?php endif ?></form></div></section></div></div></main>
